class BigNumCalculator:

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        """
        def strip_leading_zeros(s):
            return s.lstrip('0') or '0'

        # Handle negative numbers
        if num1.startswith('-') or num2.startswith('-'):
            abs1 = num1[1:] if num1.startswith('-') else num1
            abs2 = num2[1:] if num2.startswith('-') else num2
            abs1 = strip_leading_zeros(abs1)
            abs2 = strip_leading_zeros(abs2)

            abs_num1 = int(abs1)
            abs_num2 = int(abs2)
            num1_is_neg = num1.startswith('-')
            num2_is_neg = num2.startswith('-')

            if num1_is_neg and num2_is_neg:
                result_abs = abs_num1 + abs_num2
                return f'-{result_abs}'
            elif num1_is_neg and not num2_is_neg:
                if abs_num1 >= abs_num2:
                    result_abs = abs_num2 - abs_num1
                    return str(-result_abs)
                else:
                    result_abs = abs_num1 - abs_num2
                    return str(result_abs)
            elif not num1_is_neg and num2_is_neg:
                if abs_num2 >= abs_num1:
                    result_abs = abs_num1 - abs_num2
                    return str(-result_abs)
                else:
                    return abs_num2 - abs_num1
            else:
                return str(abs_num1 + abs_num2)
        else:
            return str(int(strip_leading_zeros(num1)) + int(strip_leading_zeros(num2)))

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        """
        # Handle negative numbers by extracting sign and absolute value
        sign1 = '-' if num1.startswith('-') else ''
        abs1 = num1[1:] if num1.startswith('-') else num1.strip()

        sign2 = '-' if num2.startswith('-') else ''
        abs2 = num2[1:] if num2.startswith('-') else num2.strip()

        # Convert to integers (Python handles arbitrary precision)
        val1 = int(abs1) if abs1 else 0
        val2 = int(abs2) if abs2 else 0

        result = val1 - val2

        # Handle special cases and sign
        if result == 0:
            return '0'

        # Create integer representation with signs
        int1 = val1 if sign1 != '-' else -val1
        int2 = val2 if sign2 != '-' else -val2

        diff = int1 - int2

        if diff < 0:
            return f'-{abs(diff)}'
        else:
            return str(diff)

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        """
        # Handle empty strings
        if not num1 or not num2:
            return '0'

        # Handle negative numbers by extracting sign and absolute value
        sign1 = '-' if num1.startswith('-') else ''
        abs1 = num1[1:] if num1.startswith('-') else num1.strip()

        sign2 = '-' if num2.startswith('-') else ''
        abs2 = num2[1:] if num2.startswith('-') else num2.strip()

        # Convert to integers (Python handles arbitrary precision)
        val1 = int(abs1) if abs1 else 0
        val2 = int(abs2) if abs2 else 0

        result = val1 * val2

        # Determine sign
        if result == 0:
            return '0'
        elif sign1 == '-' or sign2 == '-':
            return f'-{abs(result)}'
        else:
            return str(result)
